sp_widget.client_script:
function UserTicketLookupController($scope, $rootScope, $timeout, spUtil) {
    var c = this;

    // Initialize the reference field object for sn-record-picker
    // IMPORTANT: This structure is required by the sn-record-picker directive.
    c.userRefField = {
        displayValue: '', // The user-friendly name displayed
        value: '', // The sys_id (value-field) used in server-side queries
        name: 'user_reference' // Internal name for the field
    };

    c.searchTickets = function() {
        // Client-side validation: check for the sys_id value from the reference picker
        // If the 'value' property is empty, block the search and show an error.
        if (!c.userRefField.value) {
            c.data.error = "Please select a User (Name or ID) to search.";
            c.data.results = null; // Clear old results
            return;
        }

        c.data.error = '';
        c.data.loading = true;

        // Send the reference object's value (the sys_id) to the server
        c.data.inputs = {
            userSysId: c.userRefField.value
        };

        // Call server.update() to send the inputs and run the server script logic
        c.server.update().then(function(response) {
            c.data.loading = false;
            // The server response populates c.data.results and c.data.error
        });
    };

    c.closeTicket = function(sys_id, table_name) {
        if (!confirm("Are you sure you want to close this ticket (" + sys_id + ")?")) {
            return;
        }

        c.data.loading = true;

        c.server.get({
            action: 'close_ticket',
            sys_id: sys_id,
            table_name: table_name
        }).then(function(response) {
            c.data.loading = false;
            if (response.data.success) {
                spUtil.addInfoMessage("Ticket " + sys_id + " closed successfully.");
                c.searchTickets(); // Re-run search to refresh the list
            } else {
                spUtil.addErrorMessage("Failed to close ticket " + sys_id + ".");
            }
        });
    };

    // Initial update to populate data properties if needed
    c.server.update();
}

sp_widget.script:
(function() {
    /**

    Server Script for User Ticket Lookup Widget.

    Handles searching for tickets by user sys_id and closing tickets.
    */

    // Check if the client script sent an action request to close a ticket
    if (input && input.action === 'close_ticket') {
        data.success = closeTicket(input.sys_id, input.table_name);
        return; // Exit after closing the ticket operation is complete
    }

    // --- Default Action: Search for tickets ---
    data.hasSearched = false;
    data.error = '';
    data.results = {
        incidents: [],
        changes: [],
        problems: []
    };

    // Only run the search if we have the user Sys ID input from the client
    if (input && input.inputs && input.inputs.userSysId) {
        data.hasSearched = true;
        var userSysId = input.inputs.userSysId;

        // Search different tables using the retrieved user Sys ID
        // Note: Using appropriate caller fields for each table
        data.results.incidents = getRecords('incident', 'caller_id', userSysId);
        data.results.changes = getRecords('change_request', 'requested_by', userSysId);
        data.results.problems = getRecords('problem', 'opened_by', userSysId);
    }

    // --- Helper Functions ---

    /**
     * Fetches tickets from a specified table where the caller field matches the userSysId.
     * @param {string} tableName - The table to query (e.g., 'incident').
     * @param {string} fieldName - The field to query against (e.g., 'caller_id').
     * @param {string} userSysId - The sys_id of the user.
     * @returns {Array} An array of simplified record objects, including display and raw state values.
     */
    function getRecords(tableName, fieldName, userSysId) {
        var records = [];
        var gr = new GlideRecord(tableName);

        gr.addQuery(fieldName, userSysId);
        gr.orderByDesc('sys_created_on');
        gr.query();

        while (gr.next()) {
            // Capture both the display value and the raw integer value of the state
            var stateDisplay = gr.getDisplayValue('state');
            var stateValue = gr.getValue('state');

            records.push({
                sys_id: {
                    value: gr.sys_id.toString(),
                    label: 'Sys ID'
                },
                number: {
                    value: gr.number.toString(),
                    label: 'Number'
                },
                short_description: {
                    value: gr.short_description.toString(),
                    label: 'Short Description'
                },
                state: {
                    value: stateDisplay,
                    raw_value: stateValue,
                    label: 'State'
                }
            });
        }
        return records;
    }

    /**
     * Updates the state of the ticket to "Resolved" (3) or an equivalent closed state.
     * @param {string} sysId - The sys_id of the ticket to close.
     * @param {string} tableName - The table the ticket belongs to.
     * @returns {boolean} True if the ticket was successfully updated.
     */
    function closeTicket(sysId, tableName) {
        var gr = new GlideRecord(tableName);
        if (gr.get(sysId)) {
            // State 3 is typically Resolved/Closed in many tables.
            gr.setValue('state', 3);
            gr.setValue('active', false);
            return gr.update();
        }
        return false;
    }
})();
